namespace RonSijm.FluidHumidifier.Factories.NetworkSecurityManager;

public class DeploymentFactory(string resourceName = null, Action<Humidifier.NetworkSecurityManager.Deployment> factoryAction = null) : ResourceFactory<Humidifier.NetworkSecurityManager.Deployment>(resourceName)
{

    internal List<InnerDeploymentAssociatedPolicyFactory> AssociatedPolicyListFactories { get; set; } = [];

    internal List<InnerDeploymentAssociatedScopeFactory> AssociatedScopeListFactories { get; set; } = [];

    internal InnerDeploymentDeploymentConfigurationFactory DeploymentConfigurationFactory { get; set; }

    protected override Humidifier.NetworkSecurityManager.Deployment Create()
    {
        var deploymentResult = CreateDeployment();
        factoryAction?.Invoke(deploymentResult);

        return deploymentResult;
    }

    private Humidifier.NetworkSecurityManager.Deployment CreateDeployment()
    {
        var deploymentResult = new Humidifier.NetworkSecurityManager.Deployment
        {
            GivenName = InputResourceName,
        };

        return deploymentResult;
    }
    public override void CreateChildren(Humidifier.NetworkSecurityManager.Deployment result)
    {
        base.CreateChildren(result);

        result.AssociatedPolicyList = AssociatedPolicyListFactories.Any() ? AssociatedPolicyListFactories.Select(x => x.Build()).ToList() : null;
        result.AssociatedScopeList = AssociatedScopeListFactories.Any() ? AssociatedScopeListFactories.Select(x => x.Build()).ToList() : null;
        result.DeploymentConfiguration ??= DeploymentConfigurationFactory?.Build();
    }

} // End Of Class

